class BankAccount:
    def __init__(self):
        self.balance = 0
        self.history = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.balance += amount
        self.history.append(f"Deposited {amount}")

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self.balance:
            raise ValueError("Insufficient funds for withdrawal")
        self.balance -= amount
        self.history.append(f"Withdrew {amount}")

    def get_balance(self):
        return self.balance

    def get_history(self):
        return self.history


if __name__ == "__main__":
    import unittest

    class TestBankAccount(unittest.TestCase):
        def setUp(self):
            self.account = BankAccount()

        def test_deposit(self):
            self.account.deposit(100)
            self.assertEqual(self.account.get_balance(), 100)
            self.assertIn("Deposited 100", self.account.get_history())

        def test_withdraw(self):
            self.account.deposit(100)
            self.account.withdraw(40)
            self.assertEqual(self.account.get_balance(), 60)
            self.assertIn("Withdrew 40", self.account.get_history())

        def test_withdraw_overdraft_protection(self):
            self.account.deposit(50)
            with self.assertRaises(ValueError):
                self.account.withdraw(100)

        def test_deposit_negative(self):
            with self.assertRaises(ValueError):
                self.account.deposit(-20)

        def test_withdraw_negative(self):
            with self.assertRaises(ValueError):
                self.account.withdraw(-30)

    unittest.main()  
